// Step 1: Normalize incoming payload and extract domain
const lead = $json.body || $json;

// 1. Sanitize email & extract domain
const email = (lead.work_email || '').trim().toLowerCase();
const emailDomain = email.includes('@') ? email.split('@')[1] : '';

// 2. Identify if personal/free email provider
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com'];
const isFreeEmail = freeProviders.includes(emailDomain);

// 3. Clean website URL to root domain if provided
let cleanDomain = emailDomain;
if (lead.company_website) {
  try {
    const url = lead.company_website.startsWith('http') ? lead.company_website : 'https://' + lead.company_website;
    const parsed = new URL(url);
    cleanDomain = parsed.hostname.replace(/^www\./, '');
  } catch (e) {
    // fallback to email domain
  }
}

return {
  raw_lead: lead,
  normalized: {
    first_name: (lead.first_name || '').trim(),
    last_name: (lead.last_name || '').trim(),
    full_name: `${(lead.first_name || '').trim()} ${(lead.last_name || '').trim()}`.trim(),
    email: email,
    phone: (lead.phone || '').trim(),
    company_name: (lead.company_name || '').trim(),
    company_domain: cleanDomain,
    is_free_email: isFreeEmail,
    job_title: (lead.job_title || '').trim(),
    company_size: lead.company_size || 'Unknown',
    message: lead.message || '',
    lead_source: lead.lead_source || 'Inbound Webhook',
    ingested_at: new Date().toISOString()
  }
};

// Step 2A: Automated Data Enrichment Engine
const lead = $json.normalized;

// Firmographics intelligence database for standard benchmarks
const db = {
  "cloudscale.io": {
    "name": "CloudScale Systems",
    "industry": "B2B Cloud Infrastructure & DevOps",
    "employee_count": 320,
    "employee_range": "250-500",
    "estimated_annual_revenue": "$45M",
    "headquarters": "San Francisco, CA, USA",
    "tech_stack": ["AWS", "Kubernetes", "HubSpot", "Slack", "PostgreSQL", "Datadog"],
    "funding_stage": "Series B",
    "company_type": "B2B SaaS / Enterprise"
  },
  "growthdigital.co": {
    "name": "Growth Digital Agency",
    "industry": "Performance Marketing & Digital Services",
    "employee_count": 35,
    "employee_range": "20-50",
    "estimated_annual_revenue": "$3.8M",
    "headquarters": "Chicago, IL, USA",
    "tech_stack": ["WordPress", "Google Analytics", "Mailchimp", "Zapier"],
    "funding_stage": "Bootstrapped",
    "company_type": "Agency / Services"
  }
};

let firmographics = {};

if (lead.is_free_email) {
  firmographics = {
    "enrichment_status": "SKIPPED_PERSONAL_EMAIL",
    "industry": "Individual / Freelance",
    "employee_count": 1,
    "employee_range": "1-5",
    "estimated_annual_revenue": "N/A",
    "headquarters": "Unknown",
    "tech_stack": [],
    "company_type": "Consumer / Freelance"
  };
} else if (db[lead.company_domain]) {
  firmographics = {
    "enrichment_status": "SUCCESS_VERIFIED",
    ...db[lead.company_domain]
  };
} else {
  // Inferred enrichment for arbitrary corporate domains
  firmographics = {
    "enrichment_status": "INFERRED",
    "name": lead.company_name || lead.company_domain,
    "industry": "General Technology / Business Services",
    "employee_count": lead.company_size === '250-500' ? 350 : 25,
    "employee_range": lead.company_size,
    "estimated_annual_revenue": "Undisclosed",
    "headquarters": "Global / Remote",
    "tech_stack": ["CRM", "Cloud Services"],
    "company_type": "B2B Commercial"
  };
}

return {
  ...$json,
  firmographics: firmographics
};

// Step 2B: HubSpot CRM Deduplication & Lookup Check
// In production, this can perform a REST call to HubSpot API:
// POST https://api.hubapi.com/crm/v3/objects/contacts/search
// POST https://api.hubapi.com/crm/v3/objects/companies/search

const email = $json.normalized.email;
const domain = $json.normalized.company_domain;

// Flag whether HubSpot token is configured or running in development mode
const hubspotToken = $env.HUBSPOT_ACCESS_TOKEN || '';

// We structure the CRM lookup metadata
const crm_lookup = {
  checked_at: new Date().toISOString(),
  contact_exists: false,
  existing_contact_id: null,
  company_exists: false,
  existing_company_id: null,
  has_open_deal: false,
  lifecycle_stage: "lead",
  hubspot_mode: hubspotToken ? "LIVE_API_READY" : "SIMULATED_NEW_LEAD"
};

return {
  ...$json,
  crm_lookup: crm_lookup
};

// Step 2C: Consolidate Unified RevOps Lead Dossier
// Prepares complete structured context for Gemini AI scoring (Step 3)

const normalized = $json.normalized;
const firmographics = $json.firmographics;
const crm = $json.crm_lookup;

const dossier = {
  lead_profile: {
    full_name: normalized.full_name,
    email: normalized.email,
    title: normalized.job_title,
    is_decision_maker: /(vp|director|head|chief|cxo|founder|owner|lead)/i.test(normalized.job_title),
    inbound_message: normalized.message,
    source: normalized.lead_source
  },
  company_profile: {
    name: firmographics.name || normalized.company_name,
    domain: normalized.company_domain,
    is_b2b: !normalized.is_free_email,
    industry: firmographics.industry,
    headcount: firmographics.employee_count,
    headcount_range: firmographics.employee_range,
    revenue: firmographics.estimated_annual_revenue,
    tech_stack: firmographics.tech_stack || [],
    company_type: firmographics.company_type
  },
  crm_status: {
    contact_exists: crm.contact_exists,
    company_exists: crm.company_exists,
    lifecycle_stage: crm.lifecycle_stage
  },
  pipeline_meta: {
    enrichment_status: firmographics.enrichment_status,
    processed_timestamp: new Date().toISOString()
  }
};

return {
  lead_dossier: dossier,
  normalized: normalized,
  firmographics: firmographics,
  crm_lookup: crm
};
